algorithms.pseudocode:
function DECIDE(theory, space):
    realizable <- false
    for s in space:
        if (for all law in theory: law(s)):   # s is a model
            realizable <- true
            break
    # Consistent := not (Entails T False) := there exists a model
    consistent <- realizable
    assert realizable == consistent           # the bridge
    return (realizable, consistent)

function BUILD_TRAJECTORY(init, step, space, length):
    require init nonempty and SERIAL(step, space)
    traj <- [ any element of init ]
    repeat length-1 times:
        s <- last(traj)
        t <- some element of space with step(s, t)   # choice
        append t to traj
    return traj

function SERIAL(step, space):
    return for all s in space: exists t in space with step(s, t)
